import React from 'react';
import { BrowserRouter as Router,Route, Routes, Link} from "react-router-dom";
import WeatherPage from "./WeatherPage";
import Nav from "./Nav";
function App(){
    return (
      <Router>
        <div>
            <Routes path="/" element={<WeatherPage />}>
            </Routes>
            <Nav/>
        </div>
      </Router>
    );
}


export default App;
